INSERT INTO public.celebrations (id, name, slug, description, hero_image_url, thumbnail_url, is_active, sort_order)
VALUES
  ('weddings', 'Weddings', 'weddings', 'A considered setting for the rituals, promises, and people at the heart of your wedding. We bring together mandap, stage, floral, fabric, and rental details around your vision.', 'https://images.unsplash.com/photo-1766590864665-7c81f43c3318?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1587271636175-90d58cdad458?auto=format&fit=crop&w=800&q=82', true, 0),
  ('mehendi', 'Mehendi', 'mehendi', 'A lively gathering with room to sit close, share stories, and celebrate. Explore colorful floral details, traditional floor seating, and welcoming backdrops for your Mehendi.', 'https://images.unsplash.com/photo-1712061716395-3988a2780592?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1747041807213-197ed4037279?auto=format&fit=crop&w=800&q=82', true, 1),
  ('haldi', 'Haldi', 'haldi', 'A warm, joyful ceremony shaped by family, flowers, and tradition. Build a bright setting with marigold-inspired details, traditional seating, and considered decor.', 'https://images.unsplash.com/photo-1771992228979-542c55a34ed4?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1780227103127-399b439cdd4a?auto=format&fit=crop&w=800&q=82', true, 2),
  ('sangeet', 'Sangeet', 'sangeet', 'An evening for music, movement, and everyone coming together. Explore stage and backdrop settings, guest seating, tables, linens, and decorative details for your celebration.', 'https://images.unsplash.com/photo-1774437680301-38dded14a9ba?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1717011969223-0217a302ec6f?auto=format&fit=crop&w=800&q=82', true, 3),
  ('baby-showers', 'Baby Showers', 'baby-showers', 'A thoughtful gathering to celebrate a growing family. Create a welcoming setting with comfortable seating, soft linens, floral details, and a backdrop for sharing the day.', 'https://images.unsplash.com/photo-1743437935763-3624f213d02f?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1783924045949-b77826ca7f63?auto=format&fit=crop&w=800&q=82', true, 4),
  ('birthdays', 'Birthdays', 'birthdays', 'From an intimate family gathering to a room full of friends, explore rental pieces and decor that help make a birthday feel personal.', 'https://images.unsplash.com/photo-1755704282977-340323fa52df?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1767070807074-67d5db511d78?auto=format&fit=crop&w=800&q=82', true, 5),
  ('anniversaries', 'Anniversaries', 'anniversaries', 'A beautiful reason to gather again. Explore considered seating, intimate table settings, floral backdrops, and the details that make an anniversary celebration your own.', 'https://images.unsplash.com/photo-1776078171101-0776fd3a953f?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1768508948723-18a2a8aae34e?auto=format&fit=crop&w=800&q=82', true, 6),
  ('pooja', 'Pooja', 'pooja', 'A respectful, welcoming space for prayer and gathering. Explore traditional seating, chowki, decor details, and serveware suited to your family’s observance.', 'https://images.unsplash.com/photo-1641296834408-b09a187937d5?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1700765020008-7fd77c847f8a?auto=format&fit=crop&w=800&q=82', true, 7),
  ('griha-pravesh', 'Griha Pravesh', 'griha-pravesh', 'Mark a new beginning with a setting that feels warm and personal. Explore traditional decor, welcoming seating, linens, and serving pieces for family and friends.', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1764304589223-30bfbfdaa9ef?auto=format&fit=crop&w=800&q=82', true, 8),
  ('gatherings', 'Cultural Gatherings & Get-togethers', 'gatherings', 'Make space for the meals, milestones, and community gatherings that bring people together. Browse flexible seating, tables, linens, decor, and serveware for your occasion.', 'https://images.unsplash.com/photo-1747041807585-f38b14c04704?auto=format&fit=crop&w=1400&q=82', 'https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=800&q=82', true, 9)
