INSERT INTO public.site_content (id, section_key, title, content, is_published)
VALUES
  ('bd5390cc-1622-56ac-adde-30ab43860558'::uuid, 'homepage.hero', 'Where tradition becomes your story.', '{"eyebrow":"SOUTH ASIAN CELEBRATIONS, THOUGHTFULLY DESIGNED","headline":{"before":"Where tradition","emphasized":"your story."},"body":"A gathering of color, ritual, and the people who make it yours.","cta_label":"Explore our celebrations","cta_href":"#celebrations","image":{"image_url":"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1400&q=82","alt_text":"A couple standing together in the warm light of a celebration"}}'::jsonb, true),
  ('97738127-cb54-5264-9279-c65a8133c971'::uuid, 'homepage.introduction', 'Old-world soul. Personal by nature.', '{"eyebrow":"A HERITAGE OF CELEBRATION","headline":{"before":"Old-world soul.","emphasized":"Personal by nature."},"body":"At Events by Somia, South Asian celebrations are honored with thoughtful design and a personal touch. From the first gathering to the final detail, we help bring your traditions, loved ones, and vision together in a setting that feels unmistakably yours.","link_label":"Our way of bringing it together","link_href":"#approach"}'::jsonb, true),
  ('181922a8-bc68-5579-a68a-fd535579c6b1'::uuid, 'homepage.celebrations', 'Every reason to come together.', '{"eyebrow":"MOMENTS WORTH GATHERING FOR","headline":{"before":"Every reason to","emphasized":"come together."},"body":"Rooted in tradition, shaped around you. We create settings for the milestones and everyday moments that bring your loved ones close.","image_source":"celebrations table thumbnails"}'::jsonb, true),
  ('412bb815-6827-5061-832a-eaec7e7706bd'::uuid, 'homepage.mandap_showcase', 'Under one beautiful canopy.', '{"eyebrow":"A PLACE FOR YOUR PROMISE","headline":{"before":"Under one","emphasized":"beautiful canopy."},"body":"A mandap is more than a setting. It is the heart of the ceremony. Bring together pillars, arches, floral backdrops, and fabric details in a space that feels deeply personal.","cta_label":"Enquire about a mandap","cta_href":"#enquiry","details":["PILLARS & ARCHES","FLORAL BACKDROPS"],"image":{"image_url":"https://images.unsplash.com/photo-1772127822552-ce9ef537bdcf?auto=format&fit=crop&w=1400&q=82","alt_text":"A floral wedding arch with a ceremony aisle and guest seating"}}'::jsonb, true),
  ('df430904-1a8a-52eb-96b3-ba261e05e4ed'::uuid, 'homepage.rental_collections', 'The details that make it yours.', '{"eyebrow":"GATHERED WITH CARE","headline":{"before":"The details","emphasized":"that make it yours."},"body":"Considered pieces for a beautifully composed celebration.","cta_label":"Explore all rentals","cta_href":"/collections","cards_source":"categories and products tables"}'::jsonb, true),
  ('654b16b4-56e4-5652-aa0b-18b2d13fae5c'::uuid, 'homepage.decorative_details', 'Little rituals. Lasting beauty.', '{"eyebrow":"A CLOSER LOOK","headline":{"before":"Little rituals.","emphasized":"Lasting beauty."},"items":[{"title":"Torans","body":"A welcoming detail for an entrance or ceremony.","image":"https://images.unsplash.com/photo-1786821443562-401f9b5055f7?auto=format&fit=crop&w=800&q=82"},{"title":"Diyas & Urlis","body":"Traditional accents that bring warmth to a gathering.","image":"https://images.unsplash.com/photo-1667031232580-13bee9c42e86?auto=format&fit=crop&w=800&q=82"},{"title":"Garlands","body":"Marigold and rose garlands for meaningful moments.","image":"https://images.unsplash.com/photo-1769598249975-cd4d74fb3881?auto=format&fit=crop&w=800&q=82"},{"title":"Fanoos & Kalash","body":"Lanterns and auspicious details for a festive setting.","image":"https://images.unsplash.com/photo-1700196798611-d27af6d9c566?auto=format&fit=crop&w=800&q=82"}]}'::jsonb, true),
  ('ea6ee874-366f-55d1-bd6f-939d5cedc261'::uuid, 'homepage.process', 'From first thought to gathered together.', '{"eyebrow":"A CONSIDERED APPROACH","headline":{"before":"From first thought","emphasized":"to gathered together."},"body":"A few thoughtful steps make room for the celebration you have imagined.","steps":[{"title":"Listen","body":"Tell us about your celebration, your traditions, and what you want guests to feel."},{"title":"Shape","body":"We bring your ideas together with decor, mandap, and rental selections."},{"title":"Gather","body":"Your setting comes together around the moments you are there to share."}]}'::jsonb, true),
  ('9ab754cc-8df5-5b4c-a7be-1be799daa20c'::uuid, 'homepage.gallery_teaser', 'A feeling, in full bloom.', '{"eyebrow":"COLLECTED MOMENTS","headline":{"before":"A feeling, in","emphasized":"full bloom."},"body":"A visual reference of ceremony settings, cultural details, and rental inspiration to help you shape your own gathering.","cta_label":"Explore the Gallery","cta_href":"/gallery"}'::jsonb, true),
  ('1d97a8c8-e860-5571-ac24-edf366d5f380'::uuid, 'homepage.enquiry', 'Tell us what you’re dreaming.', '{"eyebrow":"LET’S BEGIN","headline":{"before":"Tell us what","emphasized":"you’re dreaming."},"body":"Share a few details and our team can learn what matters most to you and your celebration.","quick_question_label":"Have a quick question?"}'::jsonb, true),
  ('c054268c-1d75-518a-b4c4-450e063f71bb'::uuid, 'homepage.footer', 'Events by Somia', '{"brand_name":"EVENTS BY SOMIA","body":"Thoughtful decor and rental pieces for South Asian celebrations and cultural gatherings.","cta_label":"Request a Quote","cta_href":"/contact#enquiry","tagline":"Rooted in tradition. Designed for your story."}'::jsonb, true),
  ('a5167279-1472-574b-9b7b-21a0b85607be'::uuid, 'about.hero', 'About us', '{"eyebrow":"OUR PHILOSOPHY","body":"Royal Indian heritage meets modern American luxury. Events by Somia brings thoughtful decor and rental selections to South Asian celebrations and cultural gatherings.","image":{"image_url":"https://images.unsplash.com/photo-1744804298789-437504006ff8?auto=format&fit=crop&w=1400&q=82","alt_text":"A couple in traditional attire beneath a grove of trees"},"cta_label":"Our approach"}'::jsonb, true),
  ('2a09dd4c-9cd7-5e29-8129-6c1c6945f579'::uuid, 'about.philosophy', 'A setting should feel like it belongs to you.', '{"eyebrow":"ROOTED IN TRADITION. PERSONAL BY NATURE.","paragraphs":["Celebrations carry the stories, rituals, and people that matter to us. Our approach begins by listening to what your gathering means, then considering how its setting can reflect that meaning.","We bring traditional references and contemporary event design into conversation through thoughtful details, beautifully composed spaces, and room for personal expression. The goal is a celebration that feels considered, welcoming, and true to your vision."]}'::jsonb, true),
  ('251ab23b-ace9-59f8-a1c8-9a04223c36e5'::uuid, 'about.approach', 'From first conversation to a clear direction', '{"eyebrow":"A CONSIDERED APPROACH","steps":[{"title":"Understand the celebration","body":"Share the occasion, the traditions you want to honor, and what you hope the space will feel like."},{"title":"Explore the details","body":"Discuss decor, furniture, linens, and rental requirements that could support your plans."},{"title":"Shape the aesthetic","body":"Talk through colors, materials, floral direction, and the balance of traditional and contemporary elements."},{"title":"Coordinate the enquiry","body":"Share the event date, location, and practical requirements so the team can respond to your enquiry."}]}'::jsonb, true),
  ('696312fa-f0d9-57a7-a3ed-4c1081c3b343'::uuid, 'about.explore', 'Explore what we offer', '{"eyebrow":"FIND YOUR STARTING POINT","links":[{"eyebrow":"Discover","title":"Celebrations","href":"/celebrations"},{"eyebrow":"Browse","title":"Rental Collections","href":"/collections"},{"eyebrow":"Gather inspiration","title":"Gallery","href":"/gallery"}]}'::jsonb, true),
  ('af8237f3-9789-5021-8fb4-6c7878f07bdf'::uuid, 'about.callout', 'Let’s begin with your story.', '{"eyebrow":"LET’S BEGIN WITH YOUR IDEAS","body":"Share what you are planning and the details that matter to you.","cta_label":"Request a Quote","cta_href":"/contact#enquiry"}'::jsonb, true),
