  ('1d9edf13-4fbc-59b9-b37b-fed67d87d45b'::uuid, 'gallery.page', 'Gallery', '{"eyebrow":"EDITORIAL INSPIRATION","body":"A considered collection of ceremony settings, color, flowers, and thoughtful details to help shape your own celebration.","editorial_eyebrow":"A VISUAL REFERENCE","editorial_title":{"before":"Ideas for the moments","emphasized":"you’ll make your own."},"editorial_body":"These photographs are editorial inspiration, not a portfolio of events hosted by Events by Somia. Explore settings and details that may help you describe the celebration you have in mind.","filters":["All","Weddings","Mehendi","Haldi","Sangeet","Baby Showers","Birthdays","Anniversaries","Pooja & Traditional Celebrations","Event Decor","Rental Collections"]}'::jsonb, true),
