  ('72633b28-84b6-5b5d-91b4-4cefe61e74c0'::uuid, 'contact.page', 'Let’s begin with your story.', '{"eyebrow":"EVENTS BY SOMIA","body":"Tell us a little about the celebration you have in mind.","form_title":"Your celebration","form_note":"Fields marked * are required.","aside_title":"Tell us what you’re dreaming.","aside_body":"Share a few details and our team can learn what matters most to you and your celebration."}'::jsonb, true),
  ('dc1328da-14a7-58e3-ab5b-d3eda6a5bdec'::uuid, 'faq', 'Frequently asked questions', '{"groups":[{"title":"General","questions":[["What types of celebrations do you cater to?","The website explores weddings, Mehendi, Haldi, Sangeet, baby showers, birthdays, anniversaries, Pooja, Griha Pravesh, and cultural gatherings. Share the celebration you are planning so the team can discuss the relevant decor and rental options."],["Do you work with different South Asian cultural traditions?","Events by Somia welcomes enquiries connected to South Asian celebrations and traditions across the community. Tell us which customs and details are important to your gathering so the conversation can begin with care."],["Can I enquire about an individual rental collection?","Yes. You can explore Seating, Tables, Linens, Mandap & Stage, Decor, and Serveware, then request a quote for a particular collection or listed item."]]},{"title":"Rentals","questions":[["What types of rental items are shown?","The catalogue includes seating, tables, linens and draping, mandap and stage pieces, decor, and serveware. See each collection page for the listed items."],["Can I request multiple rental categories?","Yes. Select the relevant categories in the enquiry form and describe how you hope to use them."],["Can I ask about a specific decor item?","Yes. Mention the item in your enquiry and the team can discuss it with you. A catalogue listing is an invitation to enquire; it does not confirm availability."]]},{"title":"Event planning","questions":[["How do I request a quote?","Use the Request a Quote link to share your contact information, event details, and the services or rental collections you have in mind. You can also contact the business by phone, email, or WhatsApp."],["What information should I provide?","An event type, date, guest count, location, preferred colors, and the pieces you are considering help frame the enquiry. Add any other requirements that would help explain your plans."],["Can I share inspiration photographs?","The form does not accept file uploads. You can describe your inspiration in the requirements field and email photographs to contact@eventsbysomia.com, referring to your enquiry."],["Can I request a particular colour theme?","Yes. Add the colors or palette you have in mind to the colour theme field in the enquiry form."]]},{"title":"Booking","questions":[["How can I enquire about availability?","Contact the team with your event date and requirements. Availability is discussed individually and is not guaranteed by submitting an enquiry."],["How are rental requirements confirmed?","The team will discuss your requested items and event details with you. An enquiry alone does not reserve rentals or confirm a booking."],["How should I discuss delivery, setup, and collection?","Include your venue and event timing in your enquiry, then discuss delivery, setup, and collection directly with the business. Arrangements depend on the requirements of the individual event."]]},{"title":"Contact","questions":[["How can I contact Events by Somia?","Call +1 954-496-0556, email contact@eventsbysomia.com, or use WhatsApp at +1 954-496-0556."],["Where is the business located?","The business address provided is 9266 Delemar Ct, Wellington, FL 33414, United States. Contact the team to discuss arrangements for your event."]]}]}'::jsonb, true),
  ('e362133a-b216-5c7a-ae3c-a308e4be5bb3'::uuid, 'privacy-policy', 'Privacy Policy', '{"sections":[{"title":"Information you provide","paragraphs":["When you submit an enquiry, the form collects your name, email address, phone number and country code, event type and date, expected guest count, venue, city, state, ZIP code, selected services and rental collections, preferred colour theme, budget range, and additional requirements. Some details, such as venue, colour theme, budget, and additional requirements, are optional.","Please do not include sensitive personal information that is not needed to discuss your event."]},{"title":"How enquiry information is used","paragraphs":["The information is used to review and respond to your enquiry, discuss the event and the decor or rental requirements you described, and communicate with you about that request.","The enquiry is validated by the site’s server and, when delivery is configured, sent to the business email address through an email relay selected by the site operator. The website application does not include a customer account system or a configured enquiry database. The recipient mailbox and email relay may retain messages under their own settings and policies."]},{"title":"Service providers and external links","paragraphs":["The production website is hosted on Vercel. Page typography is served by Google Fonts, and editorial photographs are requested from Unsplash. The site links to Google Maps and WhatsApp; opening those links takes you to those services, which have their own privacy practices. Enquiry delivery uses the email relay configured by the site operator; its provider depends on that configuration and is not identified in the website source code.","These services may receive standard technical information, such as a request for a page, font, or image, when your browser loads their resources. Review each provider’s current privacy information for details about its handling of data."]},{"title":"Cookies, analytics, and storage","paragraphs":["The inspected website does not implement analytics or advertising pixels and does not set analytics or advertising cookies. It does not require a customer account or use browser storage to save an enquiry. Your browser may still process cookies or similar technologies belonging to third-party services when loading their resources or when you follow an external link.","The enquiry endpoint uses a short-lived in-memory request limit to reduce automated submissions. This is operational state, not a customer enquiry record, and its behavior depends on the server instance handling the request."]},{"title":"Your choices and contacting us","paragraphs":["You may choose not to submit an enquiry. If you have questions about information you submitted, or want to request access, correction, or deletion of an enquiry held in the business mailbox, contact contact@eventsbysomia.com. The site itself has no enquiry database from which it can retrieve or delete a message.","This notice describes the website implementation inspected for this release. It is not a legal certification or legal advice. The business should have a qualified privacy professional review applicable requirements, the chosen relay provider, retention practices, and any rights or notices required before publication."]}]}'::jsonb, true),
  ('bf309299-7578-54b1-84d2-13ad5a72b46b'::uuid, 'terms', 'Terms & Conditions', '{"sections":[{"title":"Website use and information","paragraphs":["You may use this website to learn about Events by Somia, browse celebration inspiration and rental catalogue descriptions, and submit an enquiry. Please use the enquiry form and contact links accurately and lawfully.","The website is provided for general information. Descriptions and catalogue listings are intended to help you explore possibilities. They may not show every detail of an item or reflect its current condition or availability. Contact the business to discuss the details relevant to your event."]},{"title":"Images and inspiration","paragraphs":["Photographs identified as editorial inspiration are for visual reference and are not representations of events hosted by Events by Somia or of specific rental inventory. Colours, scale, materials, and arrangements may appear differently in person. Ask the business about a particular item or design before relying on an image as a description of what can be provided."]},{"title":"Enquiries and quotes","paragraphs":["Submitting an enquiry or quote request starts a conversation only. It does not confirm a reservation, rental, event service, price, or availability. The business must respond and confirm the relevant requirements directly with you. Do not treat an automated acknowledgement or successful form submission as a confirmed booking.","Any quote, rental arrangement, payment, delivery, setup, collection, cancellation, or other event terms must be discussed and agreed directly with the business. This website does not state or guarantee those terms."]},{"title":"Communication and external services","paragraphs":["Contact details submitted through the form are used to respond to the enquiry. Calls, email, WhatsApp, Google Maps, and other external services are subject to the terms and privacy practices of their respective providers.","Links to external websites are provided for convenience. Events by Somia does not control their content or availability and does not endorse or assume responsibility for third-party websites."]},{"title":"Intellectual property","paragraphs":["Website text, visual design, branding, and other original materials are protected by applicable intellectual property laws. Third-party photographs, fonts, and marks remain subject to their respective owners’ rights and licenses. Do not copy, republish, or use website materials commercially without permission from the relevant rights holder."]},{"title":"Availability and liability","paragraphs":["The website and its information are provided for general use and may be changed or unavailable from time to time. To the extent permitted by applicable law, Events by Somia makes no guarantee that the site will be uninterrupted or that every description will be complete or current. Nothing in these terms excludes a right or liability that cannot lawfully be excluded.","These website terms do not replace or create a rental agreement. Any limitation of liability and other legal provisions should be reviewed by a qualified attorney before publication and interpreted under applicable law."]},{"title":"Contact","paragraphs":["Questions about the website terms can be sent to contact@eventsbysomia.com or discussed by phone at +1 954-496-0556. The business address provided is 9266 Delemar Ct, Wellington, FL 33414, United States."]}]}'::jsonb, true),
  ('33134232-b220-55d8-9d75-33bd0406ac29'::uuid, 'celebration:weddings', 'Weddings', '{"local":"A gathering of families","note":"A gathering of families, traditions, and forever.","palette":"Ivory, champagne & rose","collections":["Mandap & stage","Seating","Tables","Linens","Decor","Serveware"],"inspiration":["Wedding mandaps and ceremony canopies","Floral, fabric, and frame backdrops","Sweetheart tables, pillars, and arches","Traditional and contemporary seating","Torans, garlands, and serveware"]}'::jsonb, true),
  ('4018931d-9117-548c-9f0f-23952041367d'::uuid, 'celebration:mehendi', 'Mehendi', '{"local":"A joyful afternoon","note":"Color, music, and joyful anticipation.","palette":"Marigold, rose & jewel tones","collections":["Seating","Linens","Decor","Tables"],"inspiration":["Gaddi, floor mattresses, and bolsters","Colorful floral arrangements and garlands","Decorative backdrops and fabric drapes","Low chowki tables for gathering"]}'::jsonb, true),
  ('8a0c943a-a823-5746-92ee-84832c9c3d3a'::uuid, 'celebration:haldi', 'Haldi', '{"local":"A golden morning","note":"A sunlit celebration wrapped in ritual.","palette":"Saffron, marigold & ivory","collections":["Seating","Tables","Decor","Linens"],"inspiration":["Traditional seating and low chowki","Marigold and rose garlands","Warm floral and fabric backdrops","Urli, kalash, and diya accents"]}'::jsonb, true),
  ('83ab572e-5cb9-53d3-95a0-2910cd68c227'::uuid, 'celebration:sangeet', 'Sangeet', '{"local":"An evening of music","note":"A lively night made for dancing together.","palette":"Burgundy, gold & candlelight","collections":["Mandap & stage","Seating","Tables","Linens","Decor"],"inspiration":["Stage setups and statement backdrops","Pillars, arches, and decorative frames","Lounge seating and guest arrangements","Cocktail tables and event linens"]}'::jsonb, true),
  ('03a5e03b-f1a3-58de-abec-4349128493f8'::uuid, 'celebration:baby-showers', 'Baby Showers', '{"local":"A little one on the way","note":"A warm welcome for a little one.","palette":"Soft rose, ivory & champagne","collections":["Seating","Tables","Linens","Decor"],"inspiration":["Comfortable seating and sofas","Soft floral and fabric backdrops","Thoughtful tables for gifts and refreshments","Coordinated linens and decorative details"]}'::jsonb, true),
  ('fde1b09e-e691-512c-a1a5-99c1c480a360'::uuid, 'celebration:birthdays', 'Birthdays', '{"local":"A milestone worth gathering for","note":"Milestones celebrated with the people you love.","palette":"Your colors, thoughtfully gathered","collections":["Seating","Tables","Linens","Decor","Serveware"],"inspiration":["Guest seating for every kind of gathering","Cake and buffet table arrangements","Colorful backdrops and draping","Serveware for a shared meal"]}'::jsonb, true),
  ('1f133762-d3cc-540d-b610-fe09b023f471'::uuid, 'celebration:anniversaries', 'Anniversaries', '{"local":"A love renewed","note":"Honoring the story you continue to write.","palette":"Champagne, rose & warm ivory","collections":["Seating","Tables","Linens","Mandap & stage","Decor"],"inspiration":["Sweetheart table and stage settings","Lounge seating for an intimate gathering","Silk and brocade runners with soft linens","Floral backdrops and garlands"]}'::jsonb, true),
  ('44e2b05b-d1ac-5bd0-bd4c-ad165fee405b'::uuid, 'celebration:pooja', 'Pooja', '{"local":"A sacred gathering","note":"An inviting setting for meaningful tradition.","palette":"Ivory, brass & marigold","collections":["Seating","Tables","Linens","Decor","Serveware"],"inspiration":["Chowki and floor seating arrangements","Diyas, kalash, and urlis","Torans and marigold garlands","Thaal, platters, and traditional serveware"]}'::jsonb, true),
  ('bda4621f-5f1b-5c69-a5df-fe3c3d308116'::uuid, 'celebration:griha-pravesh', 'Griha Pravesh', '{"local":"A new beginning","note":"A thoughtful welcome to a new home.","palette":"Warm ivory, brass & green","collections":["Seating","Tables","Linens","Decor","Serveware"],"inspiration":["Welcoming seating for family and guests","Torans, kalash, and diya accents","Tables and linens for shared refreshments","Traditional thaal and serveware"]}'::jsonb, true),
  ('2be368e6-5470-58d9-b8e0-141259f000b3'::uuid, 'celebration:gatherings', 'Cultural Gatherings & Get-togethers', '{"local":"Time together","note":"Intimate gatherings, beautifully considered.","palette":"A palette shaped around your gathering","collections":["Seating","Tables","Linens","Decor","Serveware"],"inspiration":["Flexible seating for conversations and meals","Banquet, buffet, and cocktail tables","Linens and drapes to shape the room","Decor and serveware for a shared table"]}'::jsonb, true)
